using ModelContextProtocol;
using System.ComponentModel;

var builder = WebApplication.CreateBuilder(args);

builder.Services.AddMcpServer()
    .WithHttpTransport()
    .WithToolsFromAssembly()
    .WithResources();

var app = builder.Build();

app.MapMcp();

app.Run();

[McpServerToolType]
public static class EchoTool
{
    [McpServerTool, Description("Echoes the input message back.")]
    public static string Echo([Description("Message to echo")] string message)
        => $"Echo: {message}";

    [McpServerTool, Description("Returns the current server time in UTC.")]
    public static string GetServerTime()
        => $"Server time: {DateTime.UtcNow:O}";
}

[McpServerResourceType]
public static class ConfigResource
{
    [McpServerResource(
        UriTemplate = "config://app/settings",
        Name = "App Settings",
        Description = "Returns the application configuration data.")]
    public static string GetAppSettings()
        => """
        {
          "environment": "production",
          "version": "1.0.0",
          "features": {
            "darkMode": true,
            "maxConnections": 50
          }
        }
        """;

    [McpServerResource(
        UriTemplate = "config://app/features/{featureName}",
        Name = "Feature Flag",
        Description = "Returns the status of a specific feature flag.")]
    public static string GetFeatureFlag(string featureName)
        => $$"""
        {
          "feature": "{{featureName}}",
          "enabled": true
        }
        """;
}

